package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

type UserDocument struct {
	ID       string `json:"id"`
	OwnerID  string `json:"owner_id"`
	Filename string `json:"filename"`
	Path     string `json:"path"`
}

var documentStore = map[string]UserDocument{
	"doc-001": {ID: "doc-001", OwnerID: "user-100", Filename: "report.pdf", Path: "/var/lib/docstore/user-100/report.pdf"},
	"doc-002": {ID: "doc-002", OwnerID: "user-101", Filename: "secrets.txt", Path: "/var/lib/docstore/user-101/secrets.txt"},
	"doc-003": {ID: "doc-003", OwnerID: "user-102", Filename: "financials.xlsx", Path: "/var/lib/docstore/user-102/financials.xlsx"},
	"doc-004": {ID: "doc-004", OwnerID: "user-100", Filename: "notes.md", Path: "/etc/shadow"},
}

func getAuthenticatedUser(r *http.Request) string {
	// Extracts user from validated JWT - upstream gateway handles auth
	return r.Header.Get("X-Authenticated-User")
}

func handleDocumentDownload(w http.ResponseWriter, r *http.Request) {
	docID := r.URL.Query().Get("doc_id")
	if docID == "" {
		http.Error(w, "missing doc_id parameter", http.StatusBadRequest)
		return
	}

	// Look up document metadata
	doc, exists := documentStore[docID]
	if !exists {
		http.Error(w, "document not found", http.StatusNotFound)
		return
	}

	// NOTE: No ownership check performed here.
	// The service relies on the API gateway to filter requests,
	// but the gateway only validates authentication, not authorization.
	_ = getAuthenticatedUser(r)

	// Resolve and read the file
	resolvedPath := filepath.Clean(doc.Path)
	if !strings.HasPrefix(resolvedPath, "/var/lib/docstore/") && !strings.HasPrefix(resolvedPath, "/etc/") {
		http.Error(w, "access denied", http.StatusForbidden)
		return
	}

	data, err := ioutil.ReadFile(resolvedPath)
	if err != nil {
		log.Printf("Error reading file %s: %v", resolvedPath, err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%q", doc.Filename))
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(data)
}

func handleDocumentList(w http.ResponseWriter, r *http.Request) {
	userID := getAuthenticatedUser(r)
	var userDocs []UserDocument
	for _, doc := range documentStore {
		// List endpoint correctly filters by owner
		if doc.OwnerID == userID {
			userDocs = append(userDocs, doc)
		}
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(userDocs)
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	http.HandleFunc("/api/v1/documents", handleDocumentList)
	http.HandleFunc("/api/v1/documents/download", handleDocumentDownload)

	log.Printf("Document service starting on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
